'use client';
import {useEffect,useState,useCallback,type FormEvent,type ReactNode} from 'react';
import {Activity,ArrowUpRight,ArrowRight,CalendarDays,Check,ChevronLeft,ChevronRight,ClipboardCheck,Clock,DoorOpen,FileText,GraduationCap,LayoutDashboard,LogOut,Mail,Menu,Plus,Search,Settings,ShieldCheck,Stethoscope,Users,X,Bell,RefreshCw,Download,AlertCircle,Heart,ArrowLeftRight,CheckCircle2} from 'lucide-react';
type R=Record<string,any>;
type Field={name:string;label:string;type?:string;options?:{value:string;label:string}[];required?:boolean;hint?:string;min?:number;max?:number};
type Dialog={title:string;description?:string;action:string;fields:Field[];values?:R;payload?:R};
const roleNames:R={master:'Administrador Master',secretaria:'Secretaria',professor:'Professor',preceptor:'Preceptor',aluno:'Estudante',paciente:'Paciente'};
const statusNames:R={aberto:'Aberto',ativa:'Inscrito',aprovado:'Aprovado',pendente:'Pendente',recusado:'Recusado',correcao:'Corrigir',substituido:'Substituído',agendado:'Agendado',confirmado:'Confirmado',cancelado:'Cancelado',cancelado_paciente:'Cancelado pelo paciente',cancelado_instituicao:'A reagendar',realizado:'Realizado',nao_compareceu:'Não compareceu',reagendado:'Reagendado',solicitada:'Solicitada',encaminhada:'Encaminhada',concluida:'Concluída',espera:'Em espera',em_atendimento:'Em atendimento',resolvido:'Resolvido',presente:'Presente',ausente:'Ausente'};
const weekdays=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado'];
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());
const dateLabel=(d:string)=>new Date(d.slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const options=(rows:R[],label='name')=>rows.map(r=>({value:r.id,label:r[label]||r.id}));
const strings=(rows:string[])=>rows.map(v=>({value:v,label:v}));
const list=(v:any)=>Array.isArray(v)?v.join(', '):v||'';
function Badge({value}:{value:string}){return <span className={`badge ${['aprovado','confirmado','ativa','realizado','resolvido','presente','concluida'].includes(value)?'green':['cancelado','recusado','ausente','cancelado_paciente','nao_compareceu'].includes(value)?'red':'amber'}`}>{statusNames[value]||value}</span>;}
function Empty({children}:{children:ReactNode}){return <div className="empty"><ClipboardCheck size={32}/><h3>Tudo organizado por aqui</h3><p>{children}</p></div>;}
function FieldInput({field:f,value,onChange}:{field:Field;value:any;onChange:(v:any)=>void}){return <label className={['textarea','file','checks'].includes(f.type||'')?'field full':'field'}><span>{f.label}{f.required!==false?' *':''}</span>{f.type==='select'?<select required={f.required!==false} value={value??''} onChange={e=>onChange(e.target.value)}><option value="">Selecione</option>{f.options?.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>:f.type==='checks'?<div className="checks">{f.options?.map(o=><label key={o.value}><input type="checkbox" checked={(value||[]).includes(o.value)} onChange={e=>onChange(e.target.checked?[...(value||[]),o.value]:(value||[]).filter((v:string)=>v!==o.value))}/>{o.label}</label>)}</div>:f.type==='textarea'?<textarea rows={4} required={f.required!==false} value={value??''} onChange={e=>onChange(e.target.value)}/>:f.type==='file'?<input type="file" required accept=".pdf,.png,.jpg,.jpeg,.txt" onChange={e=>onChange(e.target.files?.[0])}/>:<input type={f.type||'text'} min={f.min} max={f.max} required={f.required!==false} value={value??''} onChange={e=>onChange(e.target.value)}/>} {f.hint&&<small>{f.hint}</small>}</label>;}

export default function ClinicApp(){
 const [data,setData]=useState<R|null>(null),[loading,setLoading]=useState(true),[page,setPage]=useState('overview'),[query,setQuery]=useState(''),[dialog,setDialog]=useState<Dialog|null>(null),[values,setValues]=useState<R>({}),[busy,setBusy]=useState(false),[toast,setToast]=useState<{message:string;error?:boolean}|null>(null),[mobile,setMobile]=useState(false),[authMode,setAuthMode]=useState('login'),[authValues,setAuthValues]=useState<R>({role:'paciente',type:'proprio'}),[publicData,setPublicData]=useState<R>({courses:[],demo:false}),[calendarOffset,setCalendarOffset]=useState(0),[selectedDate,setSelectedDate]=useState(''),[selectedCourse,setSelectedCourse]=useState(''),[chosenTransfers,setChosenTransfers]=useState<string[]>([]);
 const showToast=(message:string,error=false)=>setToast({message,error});
 const load=useCallback(async()=>{try{const r=await fetch('/api/data');if(r.status===401){setData(null);return;}const result=await r.json();if(!r.ok)throw new Error(result.error);setData(result);}catch(e){setToast({message:e instanceof Error?e.message:'Falha de conexão.',error:true});}finally{setLoading(false);}},[]);
 useEffect(()=>{load();fetch('/api/auth').then(r=>r.json()).then(setPublicData).catch(()=>{});const t=new URLSearchParams(location.search).get('reset');if(t){setAuthMode('reset');setAuthValues(v=>({...v,token:t}));}},[load]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),6500);return()=>clearTimeout(timer);},[toast]);
 useEffect(()=>{if(!dialog)return;const close=(e:KeyboardEvent)=>{if(e.key==='Escape'&&!busy)setDialog(null);};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close);},[dialog,busy]);
 function open(d:Dialog){setValues(d.values||{});setDialog(d);}
 async function act(action:string,payload:R={},message='Alteração salva com sucesso.'){setBusy(true);try{const r=await fetch('/api/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,payload})});const body=await r.json();if(!r.ok)throw new Error(body.error);await load();showToast(message);return true;}catch(e){showToast(e instanceof Error?e.message:'Não foi possível salvar.',true);return false;}finally{setBusy(false);}}
 async function submitDialog(e:FormEvent){e.preventDefault();if(!dialog)return;let payload={...dialog.payload,...values};try{
  for(const field of dialog.fields){if(field.type==='number')payload[field.name]=Number(payload[field.name]);if(field.name==='periods')payload.periods=String(payload.periods).split(',').map(s=>Number(s.trim())).filter(Boolean);if(['subjects','prerequisites','courses','documents','permissions'].includes(field.name)&&field.type!=='checks')payload[field.name]=String(payload[field.name]||'').split(',').map(s=>s.trim()).filter(Boolean);}
  if(values.file){const file:File=values.file;if(file.size>5*1024*1024)throw new Error('Arquivo maior que 5 MB.');const base64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});payload={...payload,content:base64,mime:file.type||'text/plain',filename:file.name};delete payload.file;}
  if(dialog.action==='booking'){payload.patient={type:values.type||'proprio',name:values.patient_name,cpf:values.patient_cpf,relationship:values.relationship,limitation:values.limitation};}
  if(await act(dialog.action,payload))setDialog(null);
 }catch(e){showToast(e instanceof Error?e.message:'Falha no arquivo.',true);}}
 async function authenticate(e:FormEvent){e.preventDefault();setBusy(true);try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...authValues,action:authMode})});const result=await r.json();if(!r.ok)throw new Error(result.error);if(authMode==='login'){await load();}else{showToast(result.message);setAuthMode('login');}}catch(e){showToast(e instanceof Error?e.message:'Não foi possível entrar.',true);}finally{setBusy(false);}}
 async function logout(){await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});setData(null);setPage('overview');}
 const toastEl=toast&&<div className={`toast ${toast.error?'error':''}`} role="alert">{toast.error?<AlertCircle size={19}/>:<CheckCircle2 size={19}/>}<span>{toast.message}</span><button onClick={()=>setToast(null)} aria-label="Fechar aviso"><X size={16}/></button></div>;
 if(loading)return <main className="loading"><div className="brand-icon"><Activity/></div><h2>Integra</h2><p>Preparando seu espaço de cuidado…</p></main>;
 if(!data)return <main className="login-page"><section className="login-story"><a className="brand"><span className="brand-icon"><Activity/></span><span>integra<span className="brand-caption">CLÍNICAS-ESCOLA</span></span></a><div className="story-content"><span className="eyebrow light">ENSINO QUE TRANSFORMA</span><h1>Aprender.<br/>Cuidar.<br/><em>Conectar.</em></h1><p>Um espaço para aproximar a formação acadêmica do cuidado com a comunidade.</p><div className="story-line"/><div className="story-points"><span><GraduationCap/>Ensino supervisionado</span><span><Heart/>Cuidado com pessoas</span><span><ShieldCheck/>Informações protegidas</span></div></div><div className="login-foot">ANHANGUERA GUARAPARI <span>Ciência da Computação · 2026.2</span></div></section><section className="login-form"><div className="login-box"><span className="eyebrow">BEM-VINDO À INTEGRA</span><h2>{authMode==='login'?'Seu próximo passo começa aqui.':authMode==='register'?'Faça parte desse cuidado.':authMode==='forgot'?'Recupere seu acesso.':'Crie uma nova senha.'}</h2><p className="muted">{authMode==='login'?'Acesse sua conta para acompanhar atividades e atendimentos.':'Preencha as informações abaixo para continuar.'}</p><form onSubmit={authenticate} className="form-grid">
 {authMode==='login'&&<><FieldInput field={{name:'login',label:'CPF ou e-mail'}} value={authValues.login} onChange={v=>setAuthValues({...authValues,login:v})}/><FieldInput field={{name:'password',label:'Senha',type:'password'}} value={authValues.password} onChange={v=>setAuthValues({...authValues,password:v})}/><button type="button" className="text-button full align-right" onClick={()=>setAuthMode('forgot')}>Esqueci minha senha</button></>}
 {authMode==='register'&&<>{[{name:'role',label:'Quero me cadastrar como',type:'select',options:[{value:'paciente',label:'Paciente / responsável'},{value:'aluno',label:'Estudante'}]},{name:'name',label:'Nome completo'},{name:'cpf',label:'CPF'},{name:'email',label:'E-mail',type:'email'},{name:'birth',label:'Data de nascimento',type:'date'},{name:'sex',label:'Sexo',type:'select',options:strings(['Feminino','Masculino','Não informado'])},{name:'phone',label:'Telefone',required:false},{name:'password',label:'Senha (mínimo 10 caracteres)',type:'password'},...(authValues.role==='aluno'?[{name:'course',label:'Curso',type:'select',options:strings(publicData.courses)},{name:'period',label:'Período',type:'number',min:1,max:20},{name:'registration',label:'Matrícula'}]:[])].map(f=><FieldInput key={f.name} field={f} value={authValues[f.name]} onChange={v=>setAuthValues({...authValues,[f.name]:v})}/>)}</>}
 {authMode==='forgot'&&<FieldInput field={{name:'email',label:'E-mail cadastrado',type:'email'}} value={authValues.email} onChange={v=>setAuthValues({...authValues,email:v})}/>}
 {authMode==='reset'&&<FieldInput field={{name:'password',label:'Nova senha (mínimo 10 caracteres)',type:'password'}} value={authValues.password} onChange={v=>setAuthValues({...authValues,password:v})}/>}
 <button className="button primary full" disabled={busy}>{busy?'Aguarde…':authMode==='login'?'Entrar na plataforma':authMode==='register'?'Criar minha conta':'Continuar'}<ArrowRight size={18}/></button></form><div className="login-switch">{authMode==='login'?<>Ainda não tem uma conta? <button onClick={()=>setAuthMode('register')}>Cadastre-se</button></>:<button onClick={()=>setAuthMode('login')}>Voltar para o login</button>}</div>{publicData.demo&&<div className="demo-note"><ShieldCheck size={18}/><div><strong>Ambiente de demonstração</strong><p>Use as contas fictícias e a senha informadas no README do projeto.</p><select aria-label="Selecionar conta de demonstração" value="" onChange={e=>setAuthValues({...authValues,login:`${e.target.value}@clinica.test`})}><option value="">Selecionar perfil de teste</option>{Object.keys(roleNames).map(r=><option key={r} value={r}>{roleNames[r]}</option>)}</select></div></div>}<div className="privacy-note">Seus dados são utilizados para organizar seu acesso e atendimento.</div></div></section>{toastEl}</main>;

 const d=data,me=d.me,role=me.role,staff=['master','secretaria'].includes(role);
 const userName=(id:string)=>d.users.find((u:R)=>u.id===id)?.name||'Não atribuído';
 const classFor=(id:string)=>d.classes.find((c:R)=>c.id===id);
 const roomName=(id:string)=>d.rooms.find((r:R)=>r.id===id)?.name||'Sala';
 const matching=(...v:any[])=>!query||v.join(' ').toLocaleLowerCase().includes(query.toLocaleLowerCase());
 const nav=[{id:'overview',label:'Visão geral',icon:LayoutDashboard,roles:['master','secretaria','professor','preceptor','aluno','paciente']},{id:'agenda',label:role==='paciente'?'Agendar consulta':'Agenda de encontros',icon:CalendarDays,roles:['master','secretaria','professor','preceptor','aluno','paciente']},{id:'classes',label:role==='aluno'?'Turmas e inscrições':'Turmas e estágios',icon:GraduationCap,roles:['master','professor','preceptor','aluno']},{id:'bookings',label:role==='paciente'?'Minhas consultas':'Atendimentos',icon:Stethoscope,roles:['master','secretaria','professor','preceptor','aluno','paciente']},{id:'documents',label:'Documentação',icon:ShieldCheck,roles:['master','professor','aluno']},{id:'reports',label:'Relatórios e presença',icon:FileText,roles:['professor','preceptor','aluno']},{id:'transfers',label:'Transferências',icon:ArrowLeftRight,roles:['master','professor','aluno']},{id:'availability',label:'Disponibilidade',icon:Clock,roles:['master','preceptor']},{id:'rooms',label:'Clínicas e salas',icon:DoorOpen,roles:['master','secretaria']},{id:'users',label:'Pessoas e acessos',icon:Users,roles:['master','secretaria']},{id:'issues',label:'Ocorrências',icon:AlertCircle,roles:['master','preceptor']},{id:'messages',label:'Mensagens',icon:Mail,roles:Object.keys(roleNames)},{id:'settings',label:'Configurações',icon:Settings,roles:['master']}].filter(n=>n.roles.includes(role));
 const titles:R={overview:['Visão geral','Tudo o que você precisa para organizar o próximo cuidado.'],agenda:['Agenda de encontros','Ensino e atendimento, no mesmo lugar.'],classes:['Turmas e estágios','Encontros planejados. Aprendizado compartilhado.'],bookings:['Atendimentos','Acompanhe cada etapa do cuidado com a comunidade.'],documents:['Documentação','Validação acadêmica para participar com segurança.'],reports:['Relatórios e presença','Cada encontro faz parte da jornada de aprendizado.'],transfers:['Transferências','Mudanças de turma com continuidade e acompanhamento.'],availability:['Disponibilidade','Defina onde e quando você poderá supervisionar.'],rooms:['Clínicas e salas','Espaços preparados para ensinar e cuidar.'],users:['Pessoas e acessos','Uma comunidade, diferentes responsabilidades.'],issues:['Ocorrências','Comunique necessidades e acompanhe as providências.'],messages:['Mensagens','Converse com quem acompanha sua jornada.'],settings:['Configurações','A operação se adapta a cada semestre.']};
 const upcoming=d.meetings.filter((m:R)=>m.day>=today()&&m.status==='aberto');
 function bookingDialog(m:R,slot:string){open({title:'Agendar atendimento',description:`${classFor(m.class_id)?.name} · ${dateLabel(m.day)} · ${slot}`,action:'booking',payload:{meeting_id:m.id,slot},values:{type:'proprio'},fields:[...(staff?[{name:'owner_id',label:'Paciente / responsável cadastrado',type:'select',options:options(d.users.filter((u:R)=>u.role==='paciente'))}]:[]),{name:'type',label:'O atendimento é para',type:'select',options:[{value:'proprio',label:'O titular da conta'},{value:'menor',label:'Menor de idade acompanhado'},{value:'idoso',label:'Idoso acompanhado'}]},{name:'patient_name',label:'Nome da pessoa acompanhada',required:false},{name:'patient_cpf',label:'CPF da pessoa acompanhada',required:false},{name:'relationship',label:'Parentesco',type:'select',required:false,options:strings(['Filho(a)','Sobrinho(a)','Neto(a)','Pai','Mãe','Avô','Avó','Outro'])},{name:'limitation',label:'Necessidade de acompanhamento (idoso)',type:'select',required:false,options:strings(['Visual','Auditiva','Psicológica','Coordenação','Outros'])}]});}
 function classDialog(){open({title:'Criar turma',description:'Os encontros serão gerados no semestre a partir da supervisão confirmada.',action:'class',values:{start_date:d.settings.start,end_date:d.settings.end,duration:60},fields:[{name:'name',label:'Nome da aula ou estágio'},{name:'course',label:'Curso',type:'select',options:strings(me.permissions)},{name:'availability_id',label:'Preceptor, sala e horário',type:'select',options:d.availability.map((a:R)=>({value:a.id,label:`${userName(a.preceptor_id)} · ${roomName(a.room_id)} · ${weekdays[a.weekday]} ${a.start_time}–${a.end_time}`}))},{name:'periods',label:'Períodos permitidos',hint:'Separe por vírgulas. Ex.: 8, 9, 10'},{name:'prerequisites',label:'Disciplinas exigidas',required:false,hint:'Nomes separados por vírgulas.'},{name:'start_date',label:'Primeiro dia do intervalo',type:'date'},{name:'end_date',label:'Último dia do intervalo',type:'date'},{name:'duration',label:'Duração da consulta (minutos)',type:'number',min:10,max:480}]});}
 function availabilityDialog(a?:R){open({title:a?'Editar supervisão':'Oferecer supervisão',action:'availability',payload:a?{id:a.id}:{},values:a||{students:8,patients:2,start_time:'08:00',end_time:'12:00'},fields:[...(role==='master'?[{name:'preceptor_id',label:'Preceptor',type:'select',options:options(d.users.filter((u:R)=>u.role==='preceptor'))}]:[]),{name:'room_id',label:'Sala',type:'select',options:options(d.rooms.filter((r:R)=>r.active))},{name:'weekday',label:'Dia da semana',type:'select',options:weekdays.map((label,value)=>({value:String(value),label}))},{name:'start_time',label:'Início',type:'time'},{name:'end_time',label:'Fim',type:'time'},{name:'students',label:'Limite de alunos nesta sala',type:'number',min:1},{name:'patients',label:'Pacientes por horário de consulta',type:'number',min:1}]});}
 function roomDialog(r?:R){open({title:r?'Editar sala':'Cadastrar sala',action:'room',payload:r?{id:r.id}:{},values:r||{students:8,patients:2,equipment:2},fields:[{name:'name',label:'Nome da sala'},{name:'clinic',label:'Clínica'},{name:'area',label:'Área',type:'select',options:strings(d.settings.courses)},{name:'students',label:'Capacidade de alunos',type:'number',min:1},{name:'patients',label:'Atendimentos simultâneos',type:'number',min:1},{name:'equipment',label:'Postos equipados para atendimento',type:'number',min:1}]});}
 function userDialog(u?:R){open({title:u?'Editar cadastro':'Adicionar pessoa',action:'user',payload:u?{id:u.id,active:u.active}:{},values:u?{...u,permissions:list(u.permissions),subjects:list(u.subjects)}:{role:role==='secretaria'?'paciente':'aluno',period:1},fields:[{name:'name',label:'Nome completo'},{name:'email',label:'E-mail',type:'email'},{name:'cpf',label:'CPF'},{name:'role',label:'Perfil',type:'select',options:(role==='secretaria'?['paciente']:Object.keys(roleNames)).map(value=>({value,label:roleNames[value]}))},{name:'password',label:u?'Nova senha (opcional)':'Senha inicial (mínimo 10 caracteres)',type:'password',required:!u},{name:'course',label:'Curso principal',type:'select',options:strings(d.settings.courses),required:false},{name:'period',label:'Período',type:'number',min:1,max:20},{name:'registration',label:'Matrícula',required:false},{name:'birth',label:'Nascimento',type:'date',required:false},{name:'phone',label:'Telefone',required:false},{name:'permissions',label:'Cursos autorizados para professor / preceptor',hint:'Separe os nomes dos cursos por vírgulas.',required:false},{name:'subjects',label:'Disciplinas concluídas',hint:'Separe por vírgulas.',required:false}]});}
 function reportDialog(m:R){const students=d.enrollments.filter((e:R)=>e.class_id===m.class_id&&e.status==='ativa');const appts=d.bookings.filter((b:R)=>b.meeting_id===m.id&&!b.status.startsWith('cancelado'));open({title:role==='aluno'?'Enviar relatório individual':'Enviar relatório da turma',description:`${classFor(m.class_id)?.name} · ${dateLabel(m.day)}. Prazo: ${d.settings.reportDeadline}.`,action:'report',payload:{meeting_id:m.id},fields:[{name:'file',label:'Arquivo do relatório (até 5 MB)',type:'file'},...(role==='preceptor'?[{name:'absent',label:'Alunos ausentes neste encontro',type:'checks',required:false,options:students.map((e:R)=>({value:e.student_id,label:userName(e.student_id)}))}]:[]),{name:'attended',label:'Atendimentos realizados',type:'checks',required:false,options:appts.map((b:R)=>({value:b.id,label:`${b.slot} · Atendimento ${b.id.slice(0,8)}`}))}]});}
 function meetingActions(m:R){const c=classFor(m.class_id);return <div className="row-actions">{role==='professor'&&c?.professor_id===me.id&&m.status==='aberto'&&<button className="text-button" onClick={()=>open({title:'Avisar ausência pontual',description:'O encontro continua com o preceptor. O Master não receberá pendência.',action:'professor-absence',payload:{meeting_id:m.id},fields:[{name:'reason',label:'Aviso aos alunos',type:'textarea'}]})}>Avisar ausência</button>}{['paciente','secretaria','master'].includes(role)&&m.slots?.length>0&&<button className="button primary small" onClick={()=>bookingDialog(m,m.slots[0].time)}>Agendar <ArrowUpRight size={14}/></button>}{(role==='master'||role==='professor'&&c?.professor_id===me.id)&&m.status==='aberto'&&<button className="button subtle small" onClick={()=>open({title:'Cancelar este encontro',description:'Pacientes afetados serão encaminhados à Secretaria para reagendamento.',action:'cancel-meeting',payload:{meeting_id:m.id},fields:[{name:'reason',label:'Motivo',type:'textarea'}]})}>Cancelar encontro</button>}{role==='master'&&m.day>=today()&&m.status==='cancelado'&&m.reason==='Sem preceptor'&&<button className="button small" onClick={()=>open({title:'Alocar preceptor substituto',action:'substitute',payload:{meeting_id:m.id},fields:[{name:'availability_id',label:'Disponibilidade do substituto',type:'select',options:d.availability.map((a:R)=>({value:a.id,label:`${userName(a.preceptor_id)} · ${roomName(a.room_id)} · ${weekdays[a.weekday]} ${a.start_time}`}))}]})}>Substituir preceptor</button>}</div>;}
 const scheduleTable=(rows:R[])=>rows.length?<div className="table-wrap"><table><thead><tr><th>Encontro</th><th>Turma e local</th><th>Supervisão</th><th>Situação</th><th/></tr></thead><tbody>{rows.map(m=>{const c=classFor(m.class_id);return <tr key={m.id}><td><strong>{dateLabel(m.day)}</strong><small>{c?.start_time}–{c?.end_time}</small></td><td><strong>{c?.name}</strong><small>{roomName(m.room_id)} · {c?.course}</small></td><td>{userName(m.preceptor_id)}<small>Professor: {userName(c?.professor_id)}</small></td><td><Badge value={m.status}/>{m.reason&&<small>{m.reason}</small>}</td><td>{meetingActions(m)}</td></tr>;})}</tbody></table></div>:<Empty>Nenhum encontro encontrado para este filtro.</Empty>;

 return <div className="app-shell"><aside className={`sidebar ${mobile?'visible':''}`}><a className="brand" onClick={()=>setPage('overview')}><span className="brand-icon"><Activity/></span><span>integra<span className="brand-caption">CLÍNICAS-ESCOLA</span></span></a><div className="workspace"><span className="workspace-symbol"><GraduationCap size={20}/></span><div><strong>Clínica Integrada</strong><small>Semestre {d.settings.semester}</small></div><span className="online-dot"/></div><span className="nav-caption">ESPAÇO DE TRABALHO</span><nav>{nav.map(n=><button key={n.id} className={page===n.id?'active':''} onClick={()=>{setPage(n.id);setQuery('');setMobile(false);}}><n.icon size={19}/><span>{n.label}</span>{n.id==='messages'&&d.notices.some((n:R)=>!n.seen)&&<span className="nav-dot"/>}</button>)}</nav><div className="sidebar-foot"><div className="support-card"><ShieldCheck size={20}/><div><strong>Cuidar começa aqui.</strong><small>Ensino conectado à comunidade.</small></div></div><div className="profile"><span className="avatar">{me.name.split(' ').slice(0,2).map((s:string)=>s[0]).join('')}</span><div><strong>{me.name}</strong><small>{roleNames[role]}</small></div><button aria-label="Sair da conta" onClick={logout}><LogOut size={18}/></button></div></div></aside>{mobile&&<button className="sidebar-overlay" aria-label="Fechar menu" onClick={()=>setMobile(false)}/>}
 <div className="main-shell"><header className="topbar"><div className="breadcrumbs"><button className="mobile-menu" onClick={()=>setMobile(true)} aria-label="Abrir menu"><Menu/></button><span>Clínicas-Escola</span><ChevronRight size={14}/><strong>{titles[page][0]}</strong></div><div className="topbar-right"><span className="semester-pill"><span className="online-dot"/>{d.settings.archived?'Semestre arquivado':'Semestre em andamento'}</span><button className="icon-button" aria-label="Atualizar dados" onClick={load}><RefreshCw size={18}/></button><button className="icon-button notification-button" aria-label="Ver notificações" onClick={()=>setPage('messages')}><Bell size={19}/>{d.notices.some((n:R)=>!n.seen)&&<i/>}</button><span className="avatar small-avatar">{me.name[0]}</span></div></header>
 <main className="content"><div className="page-heading"><div><div className="eyebrow">{page==='overview'?`OLÁ, ${me.name.split(' ')[0].toUpperCase()}`:'GESTÃO DAS CLÍNICAS-ESCOLA'}</div><h1>{titles[page][0]}</h1><p>{titles[page][1]}</p></div><div className="heading-action">{page==='overview'?<button className="button primary" onClick={()=>setPage(role==='paciente'?'agenda':'classes')}>{role==='paciente'?'Agendar consulta':'Ver turmas'}<ArrowUpRight size={17}/></button>:page==='classes'&&role==='professor'?<button className="button primary" onClick={classDialog}><Plus size={17}/>Nova turma</button>:page==='availability'&&['preceptor','master'].includes(role)?<button className="button primary" onClick={()=>availabilityDialog()}><Plus size={17}/>Oferecer supervisão</button>:page==='rooms'&&role==='master'?<button className="button primary" onClick={()=>roomDialog()}><Plus size={17}/>Nova sala</button>:page==='users'&&staff?<button className="button primary" onClick={()=>userDialog()}><Plus size={17}/>Adicionar pessoa</button>:null}</div></div>

 {page==='overview'&&<><div className="welcome-banner"><div><span className="eyebrow">CONECTANDO ENSINO E CUIDADO</span><h2>Mais organização.<br/>Mais espaço para cuidar.</h2><p>Acompanhe os encontros, as pessoas e os próximos passos da sua clínica.</p><button className="text-button" onClick={()=>setPage('agenda')}>Explorar a agenda <ArrowRight size={16}/></button></div><div className="banner-art" aria-hidden="true"><div className="art-ring ring-one"/><div className="art-ring ring-two"/><div className="art-card"><Heart size={36}/><span>Cuidado em conexão</span><div className="art-dots"><i/><i/><i/></div></div><div className="art-float"><GraduationCap size={24}/></div></div></div>
 <div className="stats-grid">{[{label:'Encontros programados',value:upcoming.length,detail:'No calendário disponível',icon:CalendarDays,color:'teal'},{label:'Turmas disponíveis',value:d.classes.filter((c:R)=>c.active).length,detail:`Semestre ${d.settings.semester}`,icon:GraduationCap,color:'blue'},{label:'Consultas agendadas',value:d.bookings.filter((b:R)=>['agendado','confirmado'].includes(b.status)).length,detail:'Aguardando atendimento',icon:Stethoscope,color:'peach'},{label:'Avisos não lidos',value:d.notices.filter((n:R)=>!n.seen).length,detail:'Acompanhe suas atualizações',icon:Bell,color:'purple'}].map(s=><div className="stat-card" key={s.label}><div className="stat-top"><span>{s.label}</span><span className={`stat-icon ${s.color}`}><s.icon size={20}/></span></div><strong>{String(s.value).padStart(2,'0')}</strong><small>{s.detail}</small></div>)}</div>
 <div className="overview-grid"><section className="panel"><div className="panel-heading"><div><h2>Próximos encontros</h2><p>Um olhar sobre o que vem pela frente.</p></div><button className="text-button" onClick={()=>setPage('agenda')}>Ver agenda <ArrowRight size={16}/></button></div>{scheduleTable(upcoming.slice(0,5))}</section><section className="panel"><div className="panel-heading"><div><h2>No seu radar</h2><p>Atualizações que merecem atenção.</p></div><span className="tiny-label">AGORA</span></div><div className="radar-list">{role==='aluno'&&!me.approved&&<button className="radar-item" onClick={()=>setPage('documents')}><span className="radar-icon amber"><FileText size={20}/></span><div><strong>Complete sua documentação</strong><p>A aprovação libera as turmas compatíveis.</p></div><ChevronRight size={16}/></button>}{d.notices.slice(0,4).map((n:R)=><div className="radar-item" key={n.id}><span className="radar-icon"><Bell size={19}/></span><div><strong>{n.subject}</strong><p>{n.body}</p></div></div>)}{!d.notices.length&&<div className="radar-item"><span className="radar-icon"><CheckCircle2 size={20}/></span><div><strong>Você está em dia</strong><p>Novos avisos aparecerão aqui.</p></div></div>}<div className="semester-note"><span className="eyebrow">CALENDÁRIO ACADÊMICO</span><strong>Semestre {d.settings.semester}</strong><p>{dateLabel(d.settings.start)} a {dateLabel(d.settings.end)}</p><small>Inscrições até {dateLabel(d.settings.enrollmentEnd)}</small></div></div></section></div></>}

 {page==='agenda'&&<><div className="panel calendar-panel"><div className="panel-heading"><div><h2>Encontre seu próximo encontro</h2><p>Selecione uma data e uma área.</p></div><div className="row-actions"><button className="icon-button" aria-label="Semana anterior" onClick={()=>setCalendarOffset(calendarOffset-7)}><ChevronLeft size={19}/></button><button className="button small" onClick={()=>{setCalendarOffset(0);setSelectedDate('');}}>Hoje</button><button className="icon-button" aria-label="Próxima semana" onClick={()=>setCalendarOffset(calendarOffset+7)}><ChevronRight size={19}/></button></div></div><div className="week-strip">{Array.from({length:7},(_,i)=>{const dt=new Date();dt.setDate(dt.getDate()+calendarOffset+i);const iso=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(dt);return <button className={selectedDate===iso?'selected':''} key={iso} onClick={()=>setSelectedDate(selectedDate===iso?'':iso)}><span>{weekdays[dt.getDay()].slice(0,3)}</span><strong>{dt.getDate()}</strong><i className={d.meetings.some((m:R)=>m.day===iso&&m.status==='aberto')?'has-events':''}/></button>;})}</div></div><div className="filters"><div className="search-input"><Search size={18}/><input placeholder="Buscar turma ou área…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="Filtrar por curso" value={selectedCourse} onChange={e=>setSelectedCourse(e.target.value)}><option value="">Todas as áreas</option>{d.settings.courses.map((c:string)=><option key={c}>{c}</option>)}</select>{selectedDate&&<button className="text-button" onClick={()=>setSelectedDate('')}>Limpar data <X size={14}/></button>}</div>{['paciente','secretaria'].includes(role)?<div className="card-grid">{d.meetings.filter((m:R)=>m.day>=today()&&m.status==='aberto'&&m.slots.length&&(!selectedDate||m.day===selectedDate)&&(!selectedCourse||classFor(m.class_id)?.course===selectedCourse)&&matching(classFor(m.class_id)?.name,classFor(m.class_id)?.course)).slice(0,30).map((m:R)=>{const c=classFor(m.class_id);return <article className="panel appointment-card" key={m.id}><div className="card-top"><span className="area-icon"><Stethoscope size={22}/></span><span className="tiny-label">{c?.course}</span></div><h3>{c?.name}</h3><p>{dateLabel(m.day)} · {roomName(m.room_id)}</p><div className="meta-line"><ShieldCheck size={15}/>{userName(m.preceptor_id)}</div><div className="slot-list">{m.slots.map((s:R)=><button key={s.time} onClick={()=>bookingDialog(m,s.time)}>{s.time}<small>{s.remaining} vaga(s)</small></button>)}</div></article>;})}</div>:<section className="panel">{scheduleTable(d.meetings.filter((m:R)=>(selectedDate?m.day===selectedDate:m.day>=today())&&(!selectedCourse||classFor(m.class_id)?.course===selectedCourse)&&matching(classFor(m.class_id)?.name,classFor(m.class_id)?.course)).slice(0,60))}</section>}</>}

 {page==='classes'&&<><div className="filters"><div className="search-input"><Search size={18}/><input placeholder="Buscar turma…" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="muted">{d.classes.length} turma(s) no seu acesso</span></div>{role==='aluno'&&!me.approved?<Empty>Envie seus documentos e aguarde a validação para visualizar as vagas.</Empty>:<div className="card-grid">{d.classes.filter((c:R)=>matching(c.name,c.course)).map((c:R)=>{const enrolled=d.enrollments.some((e:R)=>e.class_id===c.id&&e.student_id===me.id&&e.status==='ativa');return <article className="panel class-card" key={c.id}><div className="card-top"><span className="area-icon"><GraduationCap size={24}/></span><Badge value={enrolled?'ativa':c.enrolled>=c.students?'Sem vagas':'Vagas abertas'}/></div><span className="eyebrow">{c.course}</span><h3>{c.name}</h3><p>Períodos {list(c.periods)} · {c.semester}</p><div className="class-meta"><span><CalendarDays size={16}/>{weekdays[c.weekday]}</span><span><Clock size={16}/>{c.start_time} – {c.end_time}</span><span><DoorOpen size={16}/>{roomName(c.room_id)}</span><span><Users size={16}/>{c.enrolled} de {c.students} alunos</span></div><div className="capacity-track"><i style={{width:`${Math.min(100,c.enrolled/c.students*100)}%`}}/></div><div className="class-team"><small>PROFESSOR RESPONSÁVEL</small><strong>{userName(c.professor_id)}</strong><small>PRECEPTOR</small><strong>{userName(c.preceptor_id)}</strong></div><div className="row-actions">{['master','professor'].includes(role)&&<button className="button small" onClick={()=>open({title:'Editar regras da turma',action:'class-rules',payload:{id:c.id},values:{...c,periods:list(c.periods),prerequisites:list(c.prerequisites)},fields:[{name:'name',label:'Nome'},{name:'periods',label:'Períodos permitidos',hint:'Separe por vírgulas.'},{name:'prerequisites',label:'Disciplinas exigidas',required:false},{name:'duration',label:'Duração da consulta (minutos)',type:'number',min:10}]})}>Editar regras</button>}{role==='aluno'&&!enrolled&&<button className="button primary" disabled={busy||c.enrolled>=c.students||today()>d.settings.enrollmentEnd} onClick={()=>act('enroll',{class_id:c.id},'Inscrição confirmada para o semestre.')}>Inscrever-me<ArrowRight size={16}/></button>}{role==='master'&&<button className="button small" onClick={()=>open({title:'Professor responsável',action:'professor-change',payload:{class_id:c.id},fields:[{name:'professor_id',label:'Professor (vazio = sem avaliador)',type:'select',required:false,options:options(d.users.filter((u:R)=>u.role==='professor'))}]})}>Alterar professor</button>}<button className="text-button" onClick={()=>{setPage('agenda');setQuery(c.name);}}>Ver encontros<ArrowRight size={15}/></button></div></article>;})}</div>}</>}

 {page==='bookings'&&<section className="panel"><div className="panel-heading"><div><h2>{role==='paciente'?'Seu histórico de consultas':'Agenda de atendimentos'}</h2><p>Cancelamentos institucionais têm prioridade no reagendamento.</p></div>{['paciente','secretaria','master'].includes(role)&&<button className="button primary" onClick={()=>setPage('agenda')}><Plus size={17}/>Agendar</button>}</div>{!d.bookings.length?<Empty>As consultas agendadas aparecerão aqui.</Empty>:<div className="table-wrap"><table><thead><tr><th>Paciente / atendimento</th><th>Data e horário</th><th>Serviço</th><th>Situação</th><th>Ações</th></tr></thead><tbody>{d.bookings.map((b:R)=>{const m=d.meetings.find((m:R)=>m.id===b.meeting_id),c=classFor(m?.class_id);return <tr key={b.id}><td><strong>{b.patient.name}</strong><small>#{b.id.slice(0,8)}</small></td><td>{m?dateLabel(m.day):'—'}<small>{b.slot}</small></td><td>{c?.name}<small>{c?.course}</small></td><td><Badge value={b.status}/>{b.reason&&<small>{b.reason}</small>}</td><td><div className="row-actions">{(staff||b.owner_id===me.id)&&['agendado','confirmado'].includes(b.status)&&<>{b.status==='agendado'&&<button className="button small" disabled={busy} onClick={()=>act('booking-status',{id:b.id,status:'confirmado'})}>Confirmar</button>}<button className="text-button danger" onClick={()=>open({title:'Cancelar ou recusar consulta',action:'booking-status',payload:{id:b.id,status:'cancelado_paciente',decline:b.status==='agendado'},fields:[{name:'reason',label:'Motivo',type:'textarea'}]})}>Cancelar</button>{staff&&<button className="text-button" onClick={()=>act('booking-status',{id:b.id,status:'nao_compareceu'})}>Registrar falta</button>}</>}{staff&&b.status==='cancelado_instituicao'&&<><button className="button small" onClick={()=>setPage('agenda')}>Buscar nova vaga</button><button className="text-button" onClick={()=>act('booking-status',{id:b.id,status:'reagendado'})}>Marcar como reagendado</button></>}</div></td></tr>;})}</tbody></table></div>}</section>}

 {page==='documents'&&<><div className="info-banner"><ShieldCheck size={22}/><div><strong>{role==='aluno'?'Sua habilitação começa pela documentação':'Fila de validação por curso'}</strong><p>{role==='aluno'?`Documentos exigidos: ${d.settings.documents.join(', ')}. Prazo de inscrição: ${dateLabel(d.settings.enrollmentEnd)}.`:'Validar documentos não vincula o estudante às suas turmas. Confira curso, período e disciplinas antes de aprovar.'}</p></div>{role==='aluno'&&<button className="button primary" onClick={()=>open({title:'Enviar documento',action:'document',fields:[{name:'kind',label:'Tipo de documento',type:'select',options:strings(d.settings.documents)},{name:'file',label:'Arquivo (até 5 MB)',type:'file'}]})}><Plus size={16}/>Enviar documento</button>}</div>{role==='aluno'&&<section className="panel profile-summary"><div><h3>{me.name}</h3><p>{me.course} · {me.period}º período · Matrícula {me.registration}</p><small>Disciplinas concluídas: {list(me.subjects)||'Não informadas'}</small></div><Badge value={me.approved?'aprovado':'pendente'}/><button className="button small" onClick={()=>open({title:'Corrigir dados acadêmicos',description:'A alteração solicitará uma nova validação documental.',action:'profile',values:{...me,subjects:list(me.subjects)},fields:[{name:'name',label:'Nome'},{name:'course',label:'Curso',type:'select',options:strings(d.settings.courses)},{name:'period',label:'Período',type:'number',min:1,max:20},{name:'registration',label:'Matrícula'},{name:'phone',label:'Telefone',required:false},{name:'subjects',label:'Disciplinas concluídas',required:false,hint:'Separe por vírgulas.'}]})}>Editar dados</button></section>}<section className="panel"><div className="panel-heading"><h2>Documentos enviados</h2></div>{!d.documents.length?<Empty>Nenhum documento enviado ainda.</Empty>:<div className="table-wrap"><table><thead><tr><th>Aluno</th><th>Documento</th><th>Situação</th><th>Comentário</th><th/></tr></thead><tbody>{d.documents.map((doc:R)=><tr key={doc.id}><td><strong>{userName(doc.student_id)}</strong><small>{doc.course} · {d.users.find((u:R)=>u.id===doc.student_id)?.period}º período</small></td><td><strong>{doc.kind}</strong><a className="file-link" href={`/api/files/documents/${doc.id}`}><Download size={14}/>{doc.filename}</a></td><td><Badge value={doc.status}/></td><td>{doc.comment||'Aguardando análise'}{['master','professor'].includes(role)&&<small>Matrícula: {d.users.find((u:R)=>u.id===doc.student_id)?.registration} · Disciplinas: {list(d.users.find((u:R)=>u.id===doc.student_id)?.subjects)||'Não informadas'}</small>}</td><td>{['master','professor'].includes(role)&&doc.status!=='substituido'&&<button className="button small" onClick={()=>open({title:'Analisar documentação',description:`${userName(doc.student_id)} · ${doc.course}. Confira o arquivo e os dados acadêmicos.`,action:'review-document',payload:{id:doc.id},fields:[{name:'status',label:'Resultado',type:'select',options:[{value:'aprovado',label:'Aprovar'},{value:'correcao',label:'Solicitar correção'},{value:'recusado',label:'Recusar'}]},{name:'comment',label:'Comentário / correção solicitada',type:'textarea',required:false}]})}>Analisar</button>}</td></tr>)}</tbody></table></div>}</section></>}

 {page==='reports'&&<><div className="info-banner"><FileText size={22}/><div><strong>Relatórios por encontro</strong><p>Prazo: {d.settings.reportDeadline} do dia da aula. Alunos não enviam após o prazo; preceptores podem fazer a primeira entrega atrasada. Encontros cancelados não geram pendências.</p></div></div>{d.meetings.filter((m:R)=>m.day<=today()&&m.status!=='cancelado'&&(role!=='professor'||classFor(m.class_id)?.professor_id===me.id)).reverse().map((m:R)=>{const c=classFor(m.class_id);const reports=d.reports.filter((r:R)=>r.meeting_id===m.id);const students=d.enrollments.filter((e:R)=>e.class_id===m.class_id&&(e.status==='ativa'||e.created_at.slice(0,10)<=m.day&&(!e.ended_at||e.ended_at.slice(0,10)>=m.day)));return <section className="panel report-panel" key={m.id}><div className="panel-heading"><div><span className="eyebrow">{dateLabel(m.day)} · {c?.course}</span><h2>{c?.name}</h2></div>{['aluno','preceptor'].includes(role)&&<button className="button primary small" onClick={()=>reportDialog(m)}><Plus size={16}/>Enviar relatório</button>}</div><div className="table-wrap"><table><thead><tr><th>Autor</th><th>Entrega</th><th>Comentário</th><th/></tr></thead><tbody>{(role==='professor'?[...students.map((e:R)=>e.student_id),m.preceptor_id]:[me.id]).map((authorId:string)=>{const r=reports.find((r:R)=>r.author_id===authorId),at=d.attendance.find((a:R)=>a.meeting_id===m.id&&a.student_id===authorId);return <tr key={authorId}><td><strong>{userName(authorId)}</strong><small>{authorId===m.preceptor_id?'Preceptor · relatório da turma':'Relatório individual'}{at?` · ${statusNames[at.status]}`:''}</small></td><td>{r?<><a className="file-link" href={`/api/files/reports/${r.id}`}><Download size={14}/>{r.filename}</a><small>{r.late?'Entregue com atraso':'Entregue'}</small></>:<Badge value={at?.status==='ausente'?'Ausente por falta':'pendente'}/>}</td><td>{r?.comment||'—'}{r?.attendance?.length>0&&<small>Ausências informadas: {r.attendance.map(userName).join(', ')}</small>}{r?.attended_bookings?.length>0&&<small>Atendimentos: {r.attended_bookings.map((v:string)=>v.slice(0,8)).join(', ')}</small>}</td><td><div className="row-actions">{role==='professor'&&r&&<button className="button small" onClick={()=>open({title:'Comentar relatório',action:'report-comment',payload:{id:r.id},values:{comment:r.comment},fields:[{name:'comment',label:'Comentário',type:'textarea'}]})}>Comentar</button>}{role==='professor'&&authorId!==m.preceptor_id&&<button className="text-button" onClick={()=>open({title:'Confirmar frequência',action:'attendance',payload:{meeting_id:m.id,student_id:authorId},fields:[{name:'status',label:'Presença',type:'select',options:[{value:'presente',label:'Presente'},{value:'ausente',label:'Ausente'}]}]})}>Presença / falta</button>}</div></td></tr>;})}</tbody></table></div></section>;})}</>}

 {page==='availability'&&<><div className="info-banner"><Clock size={22}/><div><strong>Uma supervisão por vez</strong><p>Você pode oferecer alternativas de sala. Ao formar uma turma, o sistema bloqueia conflitos de supervisão.</p></div></div><div className="card-grid">{d.availability.filter((a:R)=>role==='master'||a.preceptor_id===me.id).map((a:R)=><section className="panel class-card" key={a.id}><span className="eyebrow">{weekdays[a.weekday]}</span><h3>{a.start_time} – {a.end_time}</h3><p>{roomName(a.room_id)}</p><div className="class-meta"><span><Users size={17}/>{a.students} alunos</span><span><Stethoscope size={17}/>{a.patients} pacientes por horário</span></div><div className="class-team"><small>PRECEPTOR</small><strong>{userName(a.preceptor_id)}</strong></div><button className="button small" onClick={()=>availabilityDialog(a)}>Editar disponibilidade</button></section>)}</div>{role==='master'&&<section className="panel padded"><h2>Registrar ausência de preceptor</h2><p className="muted">Os encontros afetados serão cancelados até a alocação de um substituto.</p><button className="button" onClick={()=>open({title:'Ausência de preceptor',action:'preceptor-absence',fields:[{name:'preceptor_id',label:'Preceptor',type:'select',options:options(d.users.filter((u:R)=>u.role==='preceptor'))},{name:'start',label:'Início da ausência',type:'date'},{name:'end',label:'Fim da ausência',type:'date'}]})}>Registrar ausência</button></section>}</>}

 {page==='rooms'&&<div className="card-grid">{d.rooms.map((r:R)=><section className="panel class-card" key={r.id}><div className="card-top"><span className="area-icon"><DoorOpen size={24}/></span><Badge value={r.active?'Disponível':'Indisponível'}/></div><span className="eyebrow">{r.clinic}</span><h3>{r.name}</h3><p>{r.area}</p><div className="class-meta"><span><Users size={16}/>{r.students} alunos</span><span><Stethoscope size={16}/>{r.patients} atendimentos simultâneos</span><span><ClipboardCheck size={16}/>{r.equipment} postos equipados</span></div><div className="row-actions">{role==='master'&&<button className="button small" onClick={()=>roomDialog(r)}>Editar</button>}<button className="button small" onClick={()=>open({title:'Indisponibilidade da sala',description:'Encontros e consultas do período serão cancelados com aviso para reagendamento.',action:'room-block',payload:{room_id:r.id},fields:[{name:'start',label:'Data inicial',type:'date'},{name:'end',label:'Data final',type:'date'},{name:'reason',label:'Motivo',type:'textarea'}]})}>Bloquear período</button></div></section>)}</div>}

 {page==='users'&&<section className="panel"><div className="panel-heading"><h2>Cadastros da clínica</h2><div className="search-input"><Search size={17}/><input placeholder="Buscar pessoa…" value={query} onChange={e=>setQuery(e.target.value)}/></div></div><div className="table-wrap"><table><thead><tr><th>Pessoa</th><th>Perfil</th><th>Curso / contato</th><th>Situação</th><th/></tr></thead><tbody>{d.users.filter((u:R)=>(role==='master'||u.role==='paciente')&&matching(u.name,u.email,u.cpf)).map((u:R)=><tr key={u.id}><td><strong>{u.name}</strong><small>{u.email}</small></td><td>{roleNames[u.role]}</td><td>{u.course||u.phone||'—'}<small>{u.role==='aluno'?`${u.period}º período · ${u.registration}`:''}</small></td><td><Badge value={u.active?'Ativo':'Inativo'}/></td><td>{role==='master'&&<div className="row-actions"><button className="button small" onClick={()=>userDialog(u)}>Editar</button>{u.id!==me.id&&<button className="text-button" onClick={()=>act('user',{...u,active:!u.active})}>{u.active?'Desativar':'Ativar'}</button>}</div>}</td></tr>)}</tbody></table></div></section>}

 {page==='transfers'&&<><div className="info-banner"><ArrowLeftRight size={22}/><div><strong>Uma mudança, com destino garantido</strong><p>O professor encaminha o pedido. O Master efetiva somente quando todos os alunos têm vaga no destino.</p></div>{role==='aluno'&&<button className="button primary" onClick={()=>open({title:'Solicitar transferência ao professor',action:'transfer',fields:[{name:'from_class',label:'Turma atual',type:'select',options:options(d.classes.filter((c:R)=>d.enrollments.some((e:R)=>e.class_id===c.id&&e.student_id===me.id&&e.status==='ativa')))},{name:'to_class',label:'Turma de destino',type:'select',options:options(d.classes)},{name:'reason',label:'Motivo',type:'textarea'}]})}>Solicitar transferência</button>}</div><section className="panel"><div className="panel-heading"><h2>Pedidos de transferência</h2>{role==='master'&&<button className="button primary small" disabled={!chosenTransfers.length||busy} onClick={async()=>{if(await act('transfer-execute',{ids:chosenTransfers}))setChosenTransfers([]);}}>Efetivar selecionados</button>}</div>{!d.transfers.length?<Empty>Sem pedidos de transferência.</Empty>:<div className="table-wrap"><table><thead><tr><th>Aluno</th><th>Origem → destino</th><th>Motivo</th><th>Status</th><th/></tr></thead><tbody>{d.transfers.map((t:R)=><tr key={t.id}><td>{role==='master'&&['encaminhada','espera'].includes(t.status)&&<input type="checkbox" aria-label={`Selecionar pedido de ${userName(t.student_id)}`} checked={chosenTransfers.includes(t.id)} onChange={e=>setChosenTransfers(e.target.checked?[...chosenTransfers,t.id]:chosenTransfers.filter(id=>id!==t.id))}/>} {userName(t.student_id)}</td><td>{classFor(t.from_class)?.name}<small>→ {classFor(t.to_class)?.name}</small></td><td>{t.reason}</td><td><Badge value={t.status}/></td><td>{role==='professor'&&t.status==='solicitada'&&<button className="button small" onClick={()=>act('transfer-forward',{id:t.id})}>Encaminhar ao Master</button>}</td></tr>)}</tbody></table></div>}</section>{role==='master'&&<section className="panel padded"><h2>Desistência definitiva</h2><p className="muted">Encerra o vínculo e mantém o histórico do estudante.</p><button className="button" onClick={()=>open({title:'Encerrar inscrição',action:'withdraw',fields:[{name:'id',label:'Inscrição',type:'select',options:d.enrollments.filter((e:R)=>e.status==='ativa').map((e:R)=>({value:e.id,label:`${userName(e.student_id)} · ${classFor(e.class_id)?.name}`}))}]})}>Registrar desistência</button></section>}</>}

 {page==='issues'&&<><div className="section-toolbar"><p className="muted">Avisos de sala ou ausência são analisados pelo Master.</p>{role==='preceptor'&&<button className="button primary" onClick={()=>open({title:'Comunicar problema ou ausência',action:'issue',fields:[{name:'room_id',label:'Sala relacionada',type:'select',options:options(d.rooms),required:false},{name:'subject',label:'Assunto'},{name:'body',label:'Descrição e período afetado',type:'textarea'}]})}><Plus size={16}/>Novo aviso</button>}</div><div className="card-grid">{d.issues.map((i:R)=><section className="panel class-card" key={i.id}><div className="card-top"><span className="eyebrow">{userName(i.author_id)}</span><Badge value={i.status}/></div><h3>{i.subject}</h3><p className="preserve">{i.body}</p><small>{roomName(i.room_id)} · {dateLabel(i.created_at)}</small>{role==='master'&&<div className="row-actions"><button className="button small" onClick={()=>act('issue-status',{id:i.id,status:'em_atendimento'})}>Em atendimento</button><button className="button small" onClick={()=>act('issue-status',{id:i.id,status:'resolvido'})}>Resolver</button></div>}</section>)}</div>{!d.issues.length&&<Empty>Nenhum problema comunicado.</Empty>}</>}

 {page==='messages'&&<div className="overview-grid"><section className="panel"><div className="panel-heading"><div><h2>Conversas</h2><p>Mensagens entre os participantes da clínica.</p></div><button className="button primary small" onClick={()=>open({title:'Nova mensagem',action:'message',fields:[{name:'recipient_id',label:'Destinatário',type:'select',options:options(d.users.filter((u:R)=>u.id!==me.id&&(role!=='paciente'||u.role==='secretaria')&&(u.role!=='paciente'||staff)))},{name:'subject',label:'Assunto'},{name:'body',label:'Mensagem',type:'textarea'}]})}><Plus size={15}/>Escrever</button></div>{!d.messages.length?<Empty>Suas mensagens aparecerão aqui.</Empty>:d.messages.map((m:R)=><article className="message-item" key={m.id}><span className="avatar">{userName(m.sender_id)[0]}</span><div><small>{userName(m.sender_id)} → {userName(m.recipient_id)} · {dateLabel(m.created_at)}</small><h3>{m.subject}</h3><p className="preserve">{m.body}</p></div></article>)}</section><section className="panel"><div className="panel-heading"><h2>Notificações</h2><button className="text-button" onClick={()=>act('notice-read',{},'Avisos marcados como lidos.')}>Marcar lidas</button></div>{d.notices.map((n:R)=><article className={`notice-item ${n.seen?'':'unread'}`} key={n.id}><strong>{n.subject}</strong><p>{n.body}</p><small>{dateLabel(n.created_at)}</small></article>)}{!d.notices.length&&<Empty>Sem novos avisos.</Empty>}</section></div>}

 {page==='settings'&&<><SettingsForm initial={d.settings} busy={busy} save={v=>act('settings',{data:v})}/><section className="panel"><div className="panel-heading"><div><h2>Histórico de alterações</h2><p>Registro das últimas operações administrativas.</p></div></div><div className="table-wrap"><table><thead><tr><th>Data</th><th>Responsável</th><th>Operação</th><th>Registro</th></tr></thead><tbody>{d.audit.slice(0,30).map((a:R)=><tr key={a.id}><td>{dateLabel(a.created_at)}</td><td>{userName(a.user_id)}</td><td>{a.action}</td><td className="muted">{a.target.slice(0,12)}</td></tr>)}</tbody></table></div></section><section className="panel padded"><h2>Entrega de e-mails</h2><p className="muted">{d.mail.filter((m:R)=>!m.sent_at).length} mensagem(ns) na fila · {d.mail.filter((m:R)=>m.sent_at).length} enviada(s). No Docker de demonstração, consulte o Mailpit em localhost:8025.</p></section></>}
 <footer className="content-footer"><span>Integra · Gestão das Clínicas-Escola</span><span>Ensino, cuidado e comunidade.</span></footer></main></div>
 {dialog&&<div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget&&!busy)setDialog(null);}}><section className="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div className="modal-header"><div><span className="eyebrow">CLÍNICAS-ESCOLA</span><h2 id="dialog-title">{dialog.title}</h2>{dialog.description&&<p>{dialog.description}</p>}</div><button className="icon-button" aria-label="Fechar" disabled={busy} onClick={()=>setDialog(null)}><X/></button></div><form onSubmit={submitDialog}><div className="form-grid">{dialog.fields.filter(f=>dialog.action!=='booking'||!['patient_name','patient_cpf','relationship','limitation'].includes(f.name)||values.type!=='proprio'&&(f.name!=='limitation'||values.type==='idoso')).map(f=><FieldInput key={f.name} field={f} value={values[f.name]} onChange={v=>setValues({...values,[f.name]:v})}/>)}</div><div className="modal-footer"><button type="button" className="button" disabled={busy} onClick={()=>setDialog(null)}>Voltar</button><button className="button primary" disabled={busy}>{busy?'Salvando…':'Confirmar'}<Check size={16}/></button></div></form></section></div>}{toastEl}</div>;
}

function SettingsForm({initial,busy,save}:{initial:R;busy:boolean;save:(v:R)=>Promise<boolean>}){const [v,setV]=useState<R>({...initial,courses:list(initial.courses),documents:list(initial.documents),weekdays:initial.weekdays.map(String)});const fields:Field[]=[{name:'semester',label:'Semestre'},{name:'start',label:'Início do semestre',type:'date'},{name:'end',label:'Fim do semestre',type:'date'},{name:'enrollmentEnd',label:'Encerramento das inscrições',type:'date'},{name:'open',label:'Abertura da clínica',type:'time'},{name:'close',label:'Fechamento da clínica',type:'time'},{name:'clinicStudents',label:'Capacidade simultânea de alunos',type:'number',min:1},{name:'clinicPatients',label:'Capacidade simultânea de pacientes',type:'number',min:1},{name:'reportDeadline',label:'Prazo do relatório no dia da aula',type:'time'},{name:'cancelHours',label:'Antecedência para cancelar (horas)',type:'number',min:0,max:168},{name:'courses',label:'Cursos oferecidos',hint:'Separe os nomes por vírgulas.'},{name:'documents',label:'Documentos obrigatórios',hint:'Separe os tipos por vírgulas.'},{name:'weekdays',label:'Dias de funcionamento',type:'checks',options:weekdays.map((label,i)=>({value:String(i),label}))}];return <section className="panel settings-panel"><div className="panel-heading"><div><h2>Operação e calendário acadêmico</h2><p>Configurações administráveis, sem alterar o código.</p></div><Settings size={22}/></div><form onSubmit={e=>{e.preventDefault();save({...v,courses:v.courses.split(',').map((s:string)=>s.trim()).filter(Boolean),documents:v.documents.split(',').map((s:string)=>s.trim()).filter(Boolean),weekdays:v.weekdays.map(Number)});}}><div className="form-grid">{fields.map(f=><FieldInput key={f.name} field={f} value={v[f.name]} onChange={x=>setV({...v,[f.name]:x})}/>)}<label className="checkbox-line full"><input type="checkbox" checked={v.archived} onChange={e=>setV({...v,archived:e.target.checked})}/>Arquivar semestre e bloquear novas operações acadêmicas</label></div><div className="modal-footer"><button className="button primary" disabled={busy}>Salvar configurações<Check size={16}/></button></div></form></section>;}
